"""The repository template for QuantConnect algorithms, with the confirmation-window guard inside (D-81).

The MCP hook and `qc_api.py` guard the confirmation window at the point of upload. A backtest run
**by hand in QuantConnect's web editor** passes through neither, so the guard has to travel with
the algorithm: every generated algorithm checks its own dates in `initialize` and raises before
any data is read if its start or end reaches the confirmation window, unless a registered
pre-registration id is embedded in it.

Two checks run inside the algorithm, because a hand edit in the web editor can change either:

  1. **before** the dates are set, on the declared `START` / `END` constants;
  2. **after** the strategy body has run, on the algorithm's effective `start_date` / `end_date`,
     so a body that calls `set_end_date` itself is caught too.

The boundary is written into the code from `propedge.data.window.DEVELOPMENT_END` at generation,
never typed, so it cannot drift from the value the rest of the repository enforces. A kit generated
before D-144 or D-237 moved the boundary passes the boundary it ran under (`PREVIOUS_DEVELOPMENT_END`,
`D144_DEVELOPMENT_END`), so it stays exactly the code that ran; no kit may embed a boundary later than the
repository's.

The embedded check can only see *whether* an id is present -- the registry is not in the cloud.
The registry check happens here, at generation (`confirmation_run_authorised`), and again when a
manual result is recorded (`propedge/data/manual_runs.py`).
"""
from __future__ import annotations

import re
import textwrap
from datetime import date

from propedge.data.cloud_guard import (
    CloudRunRefused,
    assert_cloud_run_allowed,
    confirmation_run_authorised,
)
from propedge.data.window import DEVELOPMENT_END

#: First line of every generated algorithm; `manual_runs.py` requires it.
MARKER = "# GENERATED by propedge/data/qc_template.py (D-81) -- do not edit by hand."

_DATE_SETTER = re.compile(r"\bset_?(start|end)_?date\s*\(", re.IGNORECASE)

_TEMPLATE = '''\
{marker}
# Confirmation-window guard embedded from propedge/data/window.py. Editing the dates below, or
# setting dates in the strategy body, does not bypass it: both are checked in initialize().
from AlgorithmImports import *
from datetime import date as _date

CONFIRMATION_START = _date({b.year}, {b.month}, {b.day})  # propedge.data.window.DEVELOPMENT_END
PREREG_ID = {prereg!r}
START = ({s.year}, {s.month}, {s.day})
END = ({e.year}, {e.month}, {e.day})


class ConfirmationWindowRefused(Exception):
    """This algorithm would read the confirmation window without a pre-registration."""


def _refuse_if_confirmation(label, d):
    if d >= CONFIRMATION_START and not PREREG_ID:
        raise ConfirmationWindowRefused(
            "REFUSED: " + label + " date " + d.isoformat() + " reaches the confirmation window "
            "opening " + CONFIRMATION_START.isoformat() + " and no registered pre-registration "
            "id is embedded (PREREG_ID). Development runs must end before it (D-49, D-81)."
        )

{preamble}
class {name}(QCAlgorithm):

    def initialize(self):
        _refuse_if_confirmation("start", _date(*START))
        _refuse_if_confirmation("end", _date(*END))
        self.set_start_date({s.year}, {s.month}, {s.day})
        self.set_end_date({e.year}, {e.month}, {e.day})
        self.setup()
        for label, d in (("start", self.start_date), ("end", self.end_date)):
            _refuse_if_confirmation("effective " + label, _date(d.year, d.month, d.day))

{body}
'''


def render_algorithm(*, name: str, start: date, end: date, body: str,
                     prereg_id: str | None = None, preamble: str = "",
                     boundary: date | None = None) -> str:
    """Generate algorithm source with the embedded guard.

    Args:
        name: the algorithm class name.
        start, end: the backtest span. Refused here if it reaches the confirmation window
            without a registered pre-registration -- the embedded check is a second layer, not
            the only one.
        body: the strategy's class members, including a `setup(self)` method. It may not set
            dates itself: hand-written dates are what the guard exists to catch.
        prereg_id: a runnable row in `prereg/REGISTRY.md`, only for a confirmation run.
        preamble: module-level code placed before the class (helpers, custom fill, fee and
            slippage models). The same date rule applies to it as to the body.
        boundary: the confirmation start embedded in the algorithm; None is the repository's
            `DEVELOPMENT_END`. Only a kit made before D-144 or D-237 passes the earlier boundary it
            ran under. A later boundary than the repository's is refused.
    """
    b = DEVELOPMENT_END if boundary is None else boundary
    if b > DEVELOPMENT_END:
        raise CloudRunRefused(
            f"boundary {b.isoformat()} is later than the repository's confirmation start "
            f"{DEVELOPMENT_END.isoformat()}; an algorithm may embed an earlier boundary, never a later one."
        )
    if prereg_id is None and end >= b:
        raise CloudRunRefused(
            f"the run ends {end.isoformat()}, on or after its embedded boundary {b.isoformat()}, and no "
            "pre-registration id authorises a confirmation run."
        )
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
        raise ValueError(f"{name!r} is not a valid class name")
    if end <= start:
        raise ValueError(f"end {end} is not after start {start}")
    if _DATE_SETTER.search(body) or _DATE_SETTER.search(preamble):
        raise CloudRunRefused(
            "the strategy body sets a start or end date itself. Dates come from the template "
            "arguments only, so the guard can check them."
        )
    if "def setup(self" not in body:
        raise ValueError("the body must define setup(self); initialize() is the template's")
    if prereg_id is not None and not confirmation_run_authorised(prereg_id):
        raise CloudRunRefused(
            f"prereg_id={prereg_id!r} is not a runnable row in prereg/REGISTRY.md; it cannot be "
            "embedded to authorise a confirmation run."
        )
    code = _TEMPLATE.format(
        marker=MARKER, b=b, prereg=prereg_id, s=start, e=end, name=name,
        preamble=(textwrap.dedent(preamble).strip("\n") + "\n\n") if preamble.strip() else "",
        body=textwrap.indent(textwrap.dedent(body).strip("\n"), "    "),
    )
    # The same guard the upload routes use must agree with what was just generated.
    assert_cloud_run_allowed(code, prereg_id=prereg_id, what=f"generated algorithm {name}")
    return code
